import React, {
  useEffect,
  useRef,
  useState,
} from 'react';

import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiBookOpen,
  FiLayers,
  FiUploadCloud,
  FiX,
  FiCheckCircle,
  FiXCircle,
  FiStar,
  FiImage,
  FiGlobe,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


const initialCourseForm = {

  // English
  title_en: '',
  description_en: '',
  short_description_en: '',
  duration_en: '',
  level_en: '',

  // Khmer
  title_km: '',
  description_km: '',
  short_description_km: '',
  duration_km: '',
  level_km: '',

  // Common
  slug: '',
  category_id: '',
  price: '',
  is_active: true,
  is_featured: false,
  order: 0,
};


const initialCategoryForm = {

  // English
  name_en: '',
  description_en: '',

  // Khmer
  name_km: '',
  description_km: '',

  // Common
  slug: '',
  is_active: true,
  order: 0,
};


const AdminCourses = () => {

  // =====================================================
  // LANGUAGE
  // =====================================================

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km' ||
    language === 'kh';


  const tr = (
    key,
    englishFallback,
    khmerFallback
  ) => {

    const translated = t(key);

    if (
      translated &&
      translated !== key
    ) {
      return translated;
    }

    return isKhmer
      ? khmerFallback
      : englishFallback;
  };


  // =====================================================
  // TAB
  // =====================================================

  const [
    activeTab,
    setActiveTab,
  ] = useState('courses');


  // =====================================================
  // DATA
  // =====================================================

  const [
    courses,
    setCourses,
  ] = useState([]);


  const [
    categories,
    setCategories,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  // =====================================================
  // COURSE STATE
  // =====================================================

  const [
    courseModalOpen,
    setCourseModalOpen,
  ] = useState(false);


  const [
    editingCourse,
    setEditingCourse,
  ] = useState(null);


  const [
    courseSubmitting,
    setCourseSubmitting,
  ] = useState(false);


  const [
    courseFormData,
    setCourseFormData,
  ] = useState({
    ...initialCourseForm,
  });


  const [
    courseImageFile,
    setCourseImageFile,
  ] = useState(null);


  const [
    courseImagePreview,
    setCourseImagePreview,
  ] = useState('');


  const courseFileRef =
    useRef(null);


  // =====================================================
  // CATEGORY STATE
  // =====================================================

  const [
    categoryModalOpen,
    setCategoryModalOpen,
  ] = useState(false);


  const [
    editingCategory,
    setEditingCategory,
  ] = useState(null);


  const [
    categorySubmitting,
    setCategorySubmitting,
  ] = useState(false);


  const [
    categoryFormData,
    setCategoryFormData,
  ] = useState({
    ...initialCategoryForm,
  });


  const [
    categoryImageFile,
    setCategoryImageFile,
  ] = useState(null);


  const [
    categoryImagePreview,
    setCategoryImagePreview,
  ] = useState('');


  const categoryFileRef =
    useRef(null);


  // =====================================================
  // API BASE URL
  // =====================================================

  const API_BASE_URL =
    process.env.REACT_APP_API_URL ||
    'http://127.0.0.1:8000';


  // =====================================================
  // IMAGE URL
  // =====================================================

  const getImageUrl = (
    image
  ) => {

    if (!image) {
      return '';
    }

    if (
      image.startsWith('http://') ||
      image.startsWith('https://') ||
      image.startsWith('blob:') ||
      image.startsWith('data:')
    ) {
      return image;
    }

    return `${API_BASE_URL}${
      image.startsWith('/')
        ? ''
        : '/'
    }${image}`;
  };


  // =====================================================
  // LOCALIZED COURSE VALUE
  // =====================================================

  const getCourseValue = (
    course,
    field
  ) => {

    if (!course) {
      return '';
    }

    if (isKhmer) {

      return (
        course[`${field}_km`] ||
        course[`${field}_en`] ||
        ''
      );
    }

    return (
      course[`${field}_en`] ||
      course[`${field}_km`] ||
      ''
    );
  };


  // =====================================================
  // LOCALIZED CATEGORY VALUE
  // =====================================================

  const getCategoryValue = (
    category,
    field
  ) => {

    if (!category) {
      return '';
    }

    if (isKhmer) {

      return (
        category[`${field}_km`] ||
        category[`${field}_en`] ||
        ''
      );
    }

    return (
      category[`${field}_en`] ||
      category[`${field}_km`] ||
      ''
    );
  };


  // =====================================================
  // CATEGORY NAME FROM COURSE
  // =====================================================

  const getCourseCategoryName = (
    course
  ) => {

    if (
      course?.category
    ) {

      const name =
        getCategoryValue(
          course.category,
          'name'
        );

      if (name) {
        return name;
      }
    }

    const category =
      categories.find(
        (item) =>
          String(item.id) ===
          String(
            course?.category_id
          )
      );

    if (!category) {

      return tr(
        'courses.noCategory',
        'No Category',
        'គ្មានប្រភេទ'
      );
    }

    return (
      getCategoryValue(
        category,
        'name'
      ) ||
      tr(
        'courses.noCategory',
        'No Category',
        'គ្មានប្រភេទ'
      )
    );
  };


  // =====================================================
  // CREATE SLUG
  // =====================================================

  const createSlug = (
    value = ''
  ) => {

    return String(value)
      .toLowerCase()
      .trim()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-|-$/g, '');
  };


  // =====================================================
  // FETCH DATA
  // =====================================================

  const fetchData = async () => {

    try {

      setLoading(true);

      const [
        coursesResponse,
        categoriesResponse,
      ] = await Promise.all([

        api.get(
          '/api/courses/'
        ),

        api.get(
          '/api/courses/categories/all'
        ),
      ]);


      setCourses(
        Array.isArray(
          coursesResponse.data
        )
          ? coursesResponse.data
          : coursesResponse.data?.items ||
            []
      );


      setCategories(
        Array.isArray(
          categoriesResponse.data
        )
          ? categoriesResponse.data
          : categoriesResponse.data?.items ||
            []
      );

    } catch (error) {

      console.error(
        'Fetch courses error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'courses.loadFailed',
            'Failed to load courses and categories.',
            'មិនអាចទាញយកវគ្គសិក្សា និងប្រភេទវគ្គសិក្សាបានទេ។'
          )
        )
      );

    } finally {

      setLoading(false);
    }
  };


  useEffect(() => {

    fetchData();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  // =====================================================
  // CLEAN BLOB URL
  // =====================================================

  useEffect(() => {

    return () => {

      if (
        courseImagePreview &&
        courseImagePreview.startsWith(
          'blob:'
        )
      ) {

        URL.revokeObjectURL(
          courseImagePreview
        );
      }


      if (
        categoryImagePreview &&
        categoryImagePreview.startsWith(
          'blob:'
        )
      ) {

        URL.revokeObjectURL(
          categoryImagePreview
        );
      }
    };

  }, [
    courseImagePreview,
    categoryImagePreview,
  ]);


  // =====================================================
  // RESET COURSE
  // =====================================================

  const resetCourseForm = () => {

    setEditingCourse(null);

    setCourseFormData({
      ...initialCourseForm,
    });

    setCourseImageFile(null);

    if (
      courseImagePreview &&
      courseImagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        courseImagePreview
      );
    }

    setCourseImagePreview('');

    if (courseFileRef.current) {
      courseFileRef.current.value = '';
    }
  };


  // =====================================================
  // OPEN COURSE
  // =====================================================

  const handleAddCourse = () => {

    resetCourseForm();

    setCourseModalOpen(true);
  };


  // =====================================================
  // CLOSE COURSE
  // =====================================================

  const closeCourseModal = () => {

    if (courseSubmitting) {
      return;
    }

    setCourseModalOpen(false);

    resetCourseForm();
  };


  // =====================================================
  // COURSE INPUT CHANGE
  // =====================================================

  const handleCourseInputChange = (
    event
  ) => {

    const {
      name,
      value,
      type,
      checked,
    } = event.target;


    setCourseFormData(
