        )
      );

      event.target.value = '';

      return;
    }


    if (
      file.size >
      5 * 1024 * 1024
    ) {

      toast.error(
        tr(
          'courses.imageTooLarge',
          'Image must be 5 MB or smaller.',
          'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
        )
      );

      event.target.value = '';

      return;
    }


    if (
      courseImagePreview &&
      courseImagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        courseImagePreview
      );
    }


    const preview =
      URL.createObjectURL(file);


    setCourseImageFile(file);

    setCourseImagePreview(
      preview
    );
