            py-1
            rounded-full
            bg-blue-50
            text-blue-700
            text-xs
            font-semibold
          "
        >
          {
            getCourseCategoryName(
              row
            )
          }
        </span>
      ),
    },


    {
      key: 'level_en',

      label: tr(
        'courses.level',
        'Level',
        'កម្រិត'
      ),

      render: (
        value,
        row
      ) => (

        <span
          className="
            text-sm
            text-blue-500
          "
        >
          {
            getCourseValue(
              row,
              'level'
            ) || '-'
          }
        </span>
      ),
    },


    {
      key: 'duration_en',

      label: tr(
        'courses.duration',
        'Duration',
        'រយៈពេល'
      ),

      render: (
        value,
        row
      ) => (

        <span
          className="
            text-sm
            text-blue-500
          "
        >
          {
            getCourseValue(
              row,
              'duration'
            ) || '-'
          }
        </span>
      ),
    },


    {
      key: 'price',

      label: tr(
        'courses.price',
        'Price',
        'តម្លៃ'
      ),

      render: (value) => (

        <span
          className="
            text-sm
            font-semibold
            text-blue-900
          "
        >
          {
            value !== null &&
            value !== undefined &&
            value !== ''
              ? `$${value}`
              : tr(
                  'courses.free',
                  'Free',
                  'ឥតគិតថ្លៃ'
                )
          }
        </span>
      ),
    },


    {
      key: 'is_active',

      label: tr(
        'common.status',
        'Status',
        'ស្ថានភាព'
      ),

      render: (value) => (

        <span
          className={`
            inline-flex
            items-center
            gap-1.5
            px-2.5
            py-1.5
            rounded-full
            text-xs
            font-semibold

            ${
              value
                ? `
                  bg-green-50
                  text-green-700
                  border
                  border-green-200
                `
                : `
                  bg-red-50
                  text-red-600
                  border
                  border-red-200
                `
            }
          `}
        >

          <span
            className={`
              w-1.5
              h-1.5
              rounded-full

              ${
                value
                  ? 'bg-green-500'
                  : 'bg-red-500'
              }
            `}
          />


          {
            value
              ? tr(
                  'common.active',
                  'Active',
                  'សកម្ម'
                )
              : tr(
                  'common.inactive',
                  'Inactive',
                  'អសកម្ម'
                )
          }

        </span>
      ),
    },


    {
      key: 'actions',

      label: tr(
        'common.actions',
        'Actions',
        'សកម្មភាព'
      ),

      render: (
        value,
        row
      ) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleEditCourse(row)
            }

            title={
              tr(
                'courses.editCourse',
                'Edit Course',
                'កែប្រែវគ្គសិក្សា'
              )
            }

            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-900
              hover:bg-blue-900
              hover:text-white
              transition
            "
          >

            <FiEdit2
              size={14}
            />

          </button>


          <button
            type="button"

            onClick={() =>
              handleDeleteCourse(
                row.id
              )
            }

            title={
              tr(
                'courses.deleteCourse',
                'Delete Course',
                'លុបវគ្គសិក្សា'
              )
            }

            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              rounded-lg
              bg-red-50
              text-red-600
              hover:bg-red-600
              hover:text-white
              transition
            "
          >

            <FiTrash2
              size={14}
            />

          </button>

        </div>
      ),
    },
  ];


  // =====================================================
  // CATEGORY COLUMNS
  // =====================================================

  const categoryColumns = [

    {
      key: 'image_url',

      label: tr(
        'courses.image',
        'Image',
        'រូបភាព'
      ),

      render: (
        value,
        row
      ) => {

        if (!value) {

          return (

            <div
              className="
                w-16
                h-12
                rounded-lg
                bg-blue-50
                flex
                items-center
                justify-center
                text-blue-900
                border
                border-blue-100
              "
            >

              <FiLayers
                size={20}
              />

            </div>
          );
        }


        return (

          <img
            src={
              getImageUrl(value)
            }

            alt={
              getCategoryValue(
                row,
                'name'
              ) ||
              'Category'
            }

            className="
              w-16
              h-12
              object-cover
              rounded-lg
              border
              border-blue-200
            "

            onError={(event) => {

              event.currentTarget.style.display =
                'none';
            }}
          />
        );
      },
    },


    {
      key: 'name_en',

      label: tr(
        'courses.categoryName',
        'Category Name',
        'ឈ្មោះប្រភេទ'
      ),

      render: (
        value,
        row
      ) => (

        <div
          className="
            max-w-[250px]
          "
        >

          <p
            className="
              text-sm
              font-bold
              text-blue-900
              truncate
            "
          >
            {
              getCategoryValue(
                row,
                'name'
              ) || '-'
            }
          </p>


          {
            row.name_en &&
            row.name_km && (

              <p
                className="
                  text-xs
                  text-blue-300
                  truncate
                  mt-1
                "
              >
                {
                  isKhmer
                    ? row.name_en
                    : row.name_km
                }
              </p>
            )
          }

        </div>
      ),
    },


    {
      key: 'slug',

      label: tr(
        'courses.slug',
        'Slug',
        'Slug'
      ),

      render: (value) => (

        <span
          className="
            text-xs
            text-blue-500
            bg-blue-50
            px-2.5
            py-1.5
            rounded-lg
          "
        >
          {value || '-'}
        </span>
      ),
    },


    {
      key: 'order',

      label: tr(
        'courses.order',
        'Order',
        'លំដាប់'
      ),

      render: (value) => (

        <span
          className="
            inline-flex
            items-center
            justify-center
            w-8
            h-8
            rounded-lg
            bg-blue-50
            text-blue-900
            text-xs
            font-bold
          "
        >
          {value ?? 0}
        </span>
      ),
    },


    {
      key: 'is_active',

      label: tr(
        'common.status',
        'Status',
        'ស្ថានភាព'
      ),

      render: (value) => (

        <span
          className={`
            inline-flex
            items-center
            gap-1.5
            px-2.5
            py-1.5
            rounded-full
            text-xs
            font-semibold

            ${
              value
                ? `
                  bg-green-50
                  text-green-700
                  border
                  border-green-200
                `
                : `
                  bg-red-50
                  text-red-600
                  border
                  border-red-200
                `
            }
          `}
        >

          <span
            className={`
              w-1.5
              h-1.5
              rounded-full

              ${
                value
                  ? 'bg-green-500'
                  : 'bg-red-500'
              }
            `}
          />


          {
            value
              ? tr(
                  'common.active',
                  'Active',
                  'សកម្ម'
                )
              : tr(
                  'common.inactive',
                  'Inactive',
                  'អសកម្ម'
                )
          }

        </span>
      ),
    },


    {
      key: 'actions',

      label: tr(
        'common.actions',
        'Actions',
        'សកម្មភាព'
      ),

      render: (
        value,
        row
      ) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleEditCategory(
                row
              )
            }

            title={
              tr(
                'courses.editCategory',
                'Edit Category',
                'កែប្រែប្រភេទ'
              )
            }

            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-900
              hover:bg-blue-900
              hover:text-white
              transition
            "
          >

            <FiEdit2
              size={14}
            />

          </button>


          <button
            type="button"

            onClick={() =>
              handleDeleteCategory(
                row.id
              )
            }

            title={
              tr(
                'courses.deleteCategory',
                'Delete Category',
                'លុបប្រភេទ'
              )
            }

            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              rounded-lg
              bg-red-50
              text-red-600
              hover:bg-red-600
              hover:text-white
              transition
            "
          >

            <FiTrash2
              size={14}
            />

          </button>

        </div>
      ),
    },
  ];


  // =====================================================
  // RETURN
  // =====================================================

  return (

    <div
      className={
        isKhmer
          ? 'w-full font-khmer'
          : 'w-full font-english'
      }
    >


      <div
        className="
          flex
          flex-col
          lg:flex-row
          lg:items-center
          lg:justify-between
          gap-4
          mb-6
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-11
              h-11
              bg-blue-900
              text-white
              rounded-xl
              flex
              items-center
              justify-center
              shadow-sm
            "
          >

            <FiBookOpen
              size={20}
            />

          </div>


          <div>

            <h1
              className="
                text-xl
                md:text-2xl
                font-bold
                text-blue-900
              "
            >
              {
                tr(
                  'courses.title',
                  'Courses Management',
                  'គ្រប់គ្រងវគ្គសិក្សា'
                )
              }
            </h1>


            <p
              className="
                text-xs
                md:text-sm
                text-blue-400
                mt-1
              "
            >
              {
                tr(
                  'courses.subtitle',
                  'Manage courses and course categories',
                  'គ្រប់គ្រងវគ្គសិក្សា និងប្រភេទវគ្គសិក្សា'
                )
              }
            </p>

          </div>

        </div>


        <div
          className="
            flex
            flex-col
            sm:flex-row
            gap-2
          "
        >

          <button
            type="button"

            onClick={
              handleAddCategory
            }

            className="
              h-10
              px-4
              inline-flex
              items-center
              justify-center
              gap-2
              bg-white
              border
              border-blue-200
              text-blue-900
              rounded-lg
              text-sm
              font-semibold
              hover:bg-blue-50
              transition
            "
          >

            <FiPlus
              size={16}
            />

            {
              tr(
                'courses.addCategory',
                'Add Category',
                'បន្ថែមប្រភេទ'
              )
            }

          </button>


          <button
            type="button"

            onClick={
              handleAddCourse
            }

            className="
              h-10
              px-4
              inline-flex
              items-center
              justify-center
              gap-2
              bg-red-600
              text-white
              rounded-lg
              text-sm
              font-semibold
              hover:bg-red-700
              transition
            "
          >

            <FiPlus
              size={16}
            />

            {
              tr(
                'courses.addCourse',
                'Add Course',
                'បន្ថែមវគ្គសិក្សា'
              )
            }

          </button>

        </div>

      </div>


      <div
        className="
          grid
          grid-cols-2
          xl:grid-cols-4
          gap-3
          mb-6
        "
      >

        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {
                  tr(
                    'courses.totalCourses',
                    'Total Courses',
                    'វគ្គសិក្សាសរុប'
                  )
                }
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-900
                  mt-1
                "
              >
                {courses.length}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                rounded-lg
                bg-blue-50
                text-blue-900
                flex
                items-center
                justify-center
              "
            >

              <FiBookOpen
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {
                  tr(
                    'courses.activeCourses',
                    'Active Courses',
                    'វគ្គសិក្សាសកម្ម'
                  )
                }
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-green-600
                  mt-1
                "
              >
                {activeCourses}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                rounded-lg
                bg-green-50
                text-green-600
                flex
                items-center
                justify-center
              "
            >

              <FiCheckCircle
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {
                  tr(
                    'courses.featuredCourses',
                    'Featured',
                    'វគ្គសិក្សាពិសេស'
                  )
                }
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-red-600
                  mt-1
                "
              >
                {featuredCourses}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                rounded-lg
                bg-red-50
                text-red-600
                flex
                items-center
                justify-center
              "
            >

              <FiStar
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {
                  tr(
                    'courses.categories',
                    'Categories',
                    'ប្រភេទវគ្គសិក្សា'
                  )
                }
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-600
                  mt-1
                "
              >
                {activeCategories}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                rounded-lg
                bg-blue-50
                text-blue-600
                flex
                items-center
                justify-center
              "
            >

              <FiLayers
                size={18}
              />

            </div>

          </div>

        </div>

      </div>


      <div
        className="
          flex
          items-center
          gap-2
          mb-4
          p-1
          bg-blue-50
          rounded-xl
          w-fit
        "
      >

        <button
          type="button"

          onClick={() =>
            setActiveTab(
              'courses'
            )
          }

          className={`
            h-10
            px-4
            rounded-lg
            text-sm
            font-semibold
            flex
            items-center
            gap-2
            transition

            ${
              activeTab ===
              'courses'
                ? `
                  bg-blue-900
                  text-white
                  shadow-sm
                `
                : `
                  text-blue-500
                  hover:bg-white
                `
            }
          `}
        >

          <FiBookOpen
            size={16}
          />

          {
            tr(
              'courses.courses',
              'Courses',
              'វគ្គសិក្សា'
            )
          }


          <span
            className={`
              min-w-[24px]
              h-6
              px-1.5
              rounded-md
              text-xs
              flex
              items-center
              justify-center

              ${
                activeTab ===
                'courses'
                  ? 'bg-white/20'
                  : 'bg-white'
              }
            `}
          >
            {courses.length}
          </span>

        </button>


        <button
          type="button"

          onClick={() =>
            setActiveTab(
              'categories'
            )
          }

          className={`
            h-10
            px-4
            rounded-lg
            text-sm
            font-semibold
            flex
            items-center
            gap-2
            transition

            ${
              activeTab ===
              'categories'
                ? `
                  bg-blue-900
                  text-white
                  shadow-sm
                `
                : `
                  text-blue-500
                  hover:bg-white
                `
            }
          `}
        >

          <FiLayers
            size={16}
          />

          {
            tr(
              'courses.categories',
              'Categories',
              'ប្រភេទ'
            )
          }


          <span
            className={`
              min-w-[24px]
              h-6
              px-1.5
              rounded-md
              text-xs
              flex
              items-center
              justify-center

              ${
                activeTab ===
                'categories'
                  ? 'bg-white/20'
                  : 'bg-white'
              }
            `}
          >
            {categories.length}
          </span>

        </button>

      </div>


      <AdminCard
        className="
          overflow-hidden
          border
          border-blue-200
          rounded-xl
          shadow-sm
        "
      >

        {
          activeTab ===
          'courses' ? (

            <AdminTable
              columns={
                courseColumns
              }

              data={
                courses
              }

              loading={
                loading
              }
            />

          ) : (

            <AdminTable
              columns={
                categoryColumns
              }

              data={
                categories
              }

              loading={
                loading
              }
            />
          )
        }

      </AdminCard>


      <AdminModal
        isOpen={
          courseModalOpen
        }

        onClose={
          closeCourseModal
        }

        title={
          editingCourse
            ? tr(
                'courses.editCourse',
                'Edit Course',
                'កែប្រែវគ្គសិក្សា'
              )
            : tr(
                'courses.createCourse',
                'Create Course',
                'បង្កើតវគ្គសិក្សា'
              )
        }
      >

        <form
          onSubmit={
            handleCourseSubmit
          }
        >

          <div
            className="
              space-y-5
            "
          >


            <div
              className="
                border
                border-blue-200
                rounded-xl
                overflow-hidden
              "
            >

              <div
                className="
                  flex
                  items-center
                  gap-2
                  px-4
                  py-3
                  bg-blue-50
                  border-b
                  border-blue-200
                "
              >

                <FiGlobe
                  className="
                    text-blue-900
                  "
                />

                <h3
                  className="
                    text-sm
                    font-bold
                    text-blue-900
                  "
                >
                  {
                    tr(
                      'courses.englishContent',
                      'English Content',
                      'មាតិកាភាសាអង់គ្លេស'
                    )
                  }
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-4
                "
              >

                <div>

                  <label className="admin-label">

                    {
                      tr(
                        'courses.englishTitle',
                        'English Course Title',
                        'ចំណងជើងវគ្គសិក្សាជាភាសាអង់គ្លេស'
                      )
                    }

                    <span
                      className="
                        text-red-600
                        ml-1
                      "
                    >
                      *
                    </span>

                  </label>


                  <input
                    type="text"

                    name="title_en"

                    value={
                      courseFormData.title_en
                    }

                    onChange={
                      handleCourseInputChange
                    }

                    className="
                      admin-input
                      font-english
                    "

                    placeholder="Web Development"

                    required
                  />

                </div>


                <div>

                  <label className="admin-label">
                    {
                      tr(
                        'courses.englishShortDescription',
                        'English Short Description',
