                      'courses.khmerContent',
                      'Khmer Content',
                      'មាតិកាភាសាខ្មែរ'
                    )
                  }
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-4
                "
              >

                <div>

                  <label className="admin-label">

                    {
                      tr(
                        'courses.khmerCategoryName',
                        'Khmer Category Name',
                        'ឈ្មោះប្រភេទជាភាសាខ្មែរ'
                      )
                    }

                    <span
                      className="
                        text-red-600
                        ml-1
                      "
                    >
                      *
                    </span>

                  </label>


                  <input
                    type="text"

                    name="name_km"

                    value={
                      categoryFormData.name_km
                    }

                    onChange={
                      handleCategoryInputChange
                    }

                    className="
                      admin-input
                      font-khmer
                    "

                    placeholder="វគ្គសិក្សាព័ត៌មានវិទ្យា"

                    required
                  />

                </div>


                <div>

                  <label className="admin-label">
                    {
                      tr(
                        'courses.khmerCategoryDescription',
                        'Khmer Description',
                        'ការពិពណ៌នាជាភាសាខ្មែរ'
                      )
                    }
                  </label>


                  <textarea
                    name="description_km"

                    value={
                      categoryFormData.description_km
                    }

                    onChange={
                      handleCategoryInputChange
                    }

                    rows={3}

                    className="
                      admin-input
                      resize-none
                      font-khmer
                    "
                  />

                </div>

              </div>

            </div>


            <div>

              <label className="admin-label">
                Slug *
              </label>


              <input
                type="text"

                name="slug"

                value={
                  categoryFormData.slug
                }

                onChange={
                  handleCategoryInputChange
                }

                className="admin-input"

                placeholder="it-courses"

                required
              />

            </div>


            <div>

              <label className="admin-label">
                {
                  tr(
                    'courses.categoryImage',
                    'Category Image',
                    'រូបភាពប្រភេទ'
                  )
                }
              </label>


              {
                !categoryImagePreview ? (

                  <div
                    onClick={() =>
                      categoryFileRef.current?.click()
                    }

                    className="
                      min-h-[140px]
                      border-2
                      border-dashed
                      border-blue-200
                      rounded-xl
                      flex
                      flex-col
                      items-center
                      justify-center
                      cursor-pointer
                      bg-blue-50
                      hover:border-blue-900
                      transition
                    "
                  >

                    <input
                      ref={
                        categoryFileRef
                      }

                      type="file"

                      accept="
                        image/jpeg,
                        image/jpg,
                        image/png,
                        image/webp
                      "

                      onChange={
                        handleCategoryImageChange
                      }

                      className="hidden"
                    />


                    <FiImage
                      size={25}
                      className="
                        text-blue-900
                        mb-2
                      "
                    />


                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {
                        tr(
                          'courses.uploadCategoryImage',
                          'Upload Category Image',
                          'បញ្ចូលរូបភាពប្រភេទ'
                        )
                      }
                    </p>


                    <p
                      className="
                        text-xs
                        text-blue-400
                        mt-1
                      "
                    >
                      JPG, JPEG, PNG, WEBP — 5 MB
                    </p>

                  </div>

                ) : (

                  <div
                    className="
                      relative
                      h-[200px]
                      rounded-xl
                      overflow-hidden
                      border
                      border-blue-200
                    "
                  >

                    <img
                      src={
                        categoryImagePreview
                      }

                      alt="Category Preview"

                      className="
                        w-full
                        h-full
                        object-cover
                      "
                    />


                    <button
                      type="button"

                      onClick={
                        removeCategoryImage
                      }

                      className="
                        absolute
                        top-3
                        right-3
                        w-9
                        h-9
                        bg-red-600
                        text-white
                        rounded-lg
                        flex
                        items-center
                        justify-center
                        hover:bg-red-700
                      "
                    >

                      <FiX size={18} />

                    </button>


                    <button
                      type="button"

                      onClick={() =>
                        categoryFileRef.current?.click()
                      }

                      className="
                        absolute
                        bottom-3
                        right-3
                        h-9
                        px-3
                        bg-white
                        text-blue-900
                        rounded-lg
                        text-xs
                        font-semibold
                        shadow
                      "
                    >
                      {
                        tr(
                          'courses.changeImage',
                          'Change Image',
                          'ប្ដូររូបភាព'
                        )
                      }
                    </button>


                    <input
                      ref={
                        categoryFileRef
                      }

                      type="file"

                      accept="
                        image/jpeg,
                        image/jpg,
                        image/png,
                        image/webp
                      "

                      onChange={
                        handleCategoryImageChange
                      }

                      className="hidden"
                    />

                  </div>
                )
              }

            </div>


            <div>

              <label className="admin-label">
                {
                  tr(
                    'courses.displayOrder',
                    'Display Order',
                    'លំដាប់បង្ហាញ'
                  )
                }
              </label>


              <input
                type="number"

                name="order"

                min="0"

                value={
                  categoryFormData.order
                }

                onChange={
                  handleCategoryInputChange
                }

                className="admin-input"
              />

            </div>


            <label
              className="
                flex
                items-center
                justify-between
                gap-3
                p-4
                bg-blue-50
                border
                border-blue-200
                rounded-xl
                cursor-pointer
              "
            >

              <div
                className="
                  flex
                  items-center
                  gap-3
                "
              >

                <div
                  className={`
                    w-9
                    h-9
                    rounded-lg
                    flex
                    items-center
                    justify-center

                    ${
                      categoryFormData.is_active
                        ? `
                          bg-green-100
                          text-green-600
                        `
                        : `
                          bg-blue-100
                          text-blue-400
                        `
                    }
                  `}
                >

                  {
                    categoryFormData.is_active
                      ? (
                        <FiCheckCircle />
                      )
                      : (
                        <FiXCircle />
                      )
                  }

                </div>


                <div>

                  <p
                    className="
                      text-sm
                      font-semibold
                      text-blue-900
                    "
                  >
                    {
                      tr(
                        'courses.activeCategory',
                        'Active Category',
                        'ប្រភេទសកម្ម'
                      )
                    }
                  </p>


                  <p
                    className="
                      text-xs
                      text-blue-400
                    "
                  >
                    {
                      tr(
                        'courses.activeCategoryHelp',
                        'Show this category on the website',
                        'បង្ហាញប្រភេទនេះនៅលើគេហទំព័រ'
                      )
                    }
                  </p>

                </div>

              </div>


              <input
                type="checkbox"

                name="is_active"

                checked={
                  categoryFormData.is_active
                }

                onChange={
                  handleCategoryInputChange
                }

                className="
                  w-4
                  h-4
                  accent-blue-900
                "
              />

            </label>

          </div>


          <div
            className="
              mt-6
              pt-4
              border-t
              border-blue-200
              flex
              flex-col-reverse
              sm:flex-row
              justify-end
              gap-3
            "
          >

            <button
              type="button"

              onClick={
                closeCategoryModal
              }

              disabled={
                categorySubmitting
              }

              className="
                h-10
                px-4
                bg-white
                border
                border-blue-200
                text-blue-500
                rounded-lg
                text-sm
                font-semibold
                hover:bg-blue-50
                disabled:opacity-50
              "
            >
              {
                tr(
                  'common.cancel',
                  'Cancel',
                  'បោះបង់'
                )
              }
            </button>


            <button
              type="submit"

              disabled={
                categorySubmitting
              }

              className="
                min-w-[150px]
                h-10
                px-5
                bg-red-600
                text-white
                rounded-lg
                text-sm
                font-semibold
                hover:bg-red-700
                disabled:opacity-50
                disabled:cursor-not-allowed
              "
            >
              {
                categorySubmitting
                  ? editingCategory
                    ? tr(
                        'courses.updating',
                        'Updating...',
                        'កំពុងកែប្រែ...'
                      )
                    : tr(
                        'courses.creating',
                        'Creating...',
                        'កំពុងបង្កើត...'
                      )
                  : editingCategory
                    ? tr(
                        'courses.updateCategory',
                        'Update Category',
                        'រក្សាទុកការកែប្រែ'
                      )
                    : tr(
                        'courses.createCategory',
                        'Create Category',
                        'បង្កើតប្រភេទ'
                      )
              }
            </button>

          </div>

        </form>

      </AdminModal>

    </div>
  );
};


export default AdminCourses;
